377	  // replay structurally supersedes an expired, unswept lease: the stale
378	  // share never occupied the reconstructed owner table, so its node leaves
379	  // the owner heap without any live-usage movement. Tokens are globally
380	  // unique, so matching the token alone (not the heap sequence) separates a
381	  // superseded lease from a fresh credential that happens to share seq 0.
382	  function removeHeapNodes(heap, token) {
